import * as path from 'path';
import * as fs from 'fs';
import * as minimist from 'minimist';
import * as chalk from 'chalk';
import * as resolve from 'resolve';
import SearchResults from './SearchResults';

/**
 * This class is responsible for recursively searching through the
 * packages in the specified root folder (and all packages it links to),
 * and generating a list of ignore-able dependencies. Any package that is
 * a development dependency, but not a production dependency, will be outputted
 * as part of an ignore list.
 *
 * Since the process of generating an ignore list by searching dependencies is
 * a little slow, the results will be cached in an .syncignore-auto file, which will be
 * used on the next execution. However, callers can use a "--force" option to
 * override this and require the search.
 * @class SyncIgnore
 * @param  {string} cwd working folder to use; otherwise use current working directory
 */
export default class SyncIgnore {

    /**
     * The current working directory
     * @name SyncIgnore#_cwd
     * @private
     * @type {String}
     */
    private _cwd:string;

    /**
     * If should add some extra debugging logs
     * @name SyncIgnore#_debug
     * @private
     * @type {String}
     */
    private _debug:boolean;

    /**
     * Get the default file name
     * @name SyncIgnore.FILENAME
     * @default .syncignore-auto
     * @type {string}
     */
    static get FILENAME(): string {
        return '.syncignore-auto';
    }

    /**
     * Get the default file name for manual files.
     * @name SyncIgnore.FILENAME_LOCAL
     * @default .syncignore
     * @type {string}
     */
    static get FILENAME_LOCAL(): string {
        return '.syncignore';
    }

    /**
     * This is helper node.js script for launching the SyncIgnore utility. It can be used
     * for testing.
     *
     * Run it from the package that you want to generate an ignore list for. The output
     * will be a list of files sent to stdout. The same list will appear in the .syncignore-auto
     * file.
     *
     * Parameters:
     *   --force: forces the search process; if not set, the contents of .syncignore-auto
     *            (if present) will be used.
     *   --verbose or --debug: print out debugging info
     *   --empty: creates an empty .syncignore-auto file
     * @method SyncIgnore.cli
     */
    static cli(): void {
        const args = minimist(process.argv.slice(2), {
            boolean: [
                'force',
                'debug',
                'verbose',
                'empty'
            ],
            alias: {
                f: 'force',
                d: 'debug',
                e: 'empty',
                v: 'verbose'
            },
            default: {
                force: false,
                debug: false,
                empty: false,
                verbose: false
            }
        });
        const dir:string = args._[0] || process.cwd();
        const syncignore = new SyncIgnore(path.resolve(dir));
        const debug:boolean = args.debug || args.verbose;
        let packages;
        if (args.empty) {
            packages = syncignore.fakeExec();
        } else {
            packages = syncignore.exec(args.force, debug);
        }

        if (debug) {
            console.log(chalk.gray(packages.join('\n')), '\n');
            console.log(chalk.bold.yellow('Contains %d files to ignore.\n'), packages.length);
        }
        else {
            console.log(packages.join('\n'));
        }
    }

    /**
     * Constructs SyncIgnore instance
     */
    constructor(cwd?:string) {
        this._cwd = cwd || process.cwd();
        this._debug = false;
    }

    /**
     * Execute SyncIgnore program
     * @method SyncIgnore#exec
     * @param  {boolean}  force force full search, even if syncignore-auto file
     *                          exists
     * @param  {boolean}  debug if true, debugging info will be printed to
     *                          console log
     * @return {string[]} array of package names (to ignore)
     */
    exec(force:boolean, debug:boolean):string[] {

        this._debug = debug;
        const cachePath = path.join(this._cwd, SyncIgnore.FILENAME);

        if (force || !fs.existsSync(cachePath)) {
            if (debug) {
                console.log(chalk.green("\nSearching node_modules for files to ignore...\n"));
            }
            const results:SearchResults = new SearchResults(this._cwd);
            this._search(this._cwd, results);

            const packages:string[] = results.process();
            fs.writeFileSync(cachePath, packages.join('\n'));
            results.destroy();
            return packages;
        }
        else {
            if (debug) {
                console.log(chalk.green("Using %s cached ignore file"), SyncIgnore.FILENAME);
            }
            const data:string = fs.readFileSync(cachePath, 'utf8');
            return data.split(/[\n\r]/g);
        }
    }

    /**
     * Noop for exec
     * @method SyncIgnore#fakeExec
     * @return {Array<string>} Results
     */
    fakeExec():string[] {
        const cachePath:string = path.join(this._cwd, SyncIgnore.FILENAME);
        fs.writeFileSync(cachePath, '');
        return [];
    }

    /**
     * Execute full search of folder tree, with the root being the specified
     * path.
     * @function SyncIgnore#_search
     * @private
     * @param  {string} packagePath root path
     * @return {SearchResults} results The results to update
     */
    _search(packagePath:string, results:SearchResults): void
    {
        const packageFile:string = 'package.json';
        let pkg;
        try {
            pkg = require(path.join(packagePath, packageFile));
        }
        catch(e) {
            return;
        }

        const dependencies:string[] = []
            .concat(Object.keys(pkg.dependencies || []))
            .concat(Object.keys(pkg.optionalDependencies || []));

        for (let i:number = 0; i < dependencies.length; i++) {
            const name:string = dependencies[i];
            try {
                const modulePath:string = resolve.sync(
                    path.join(name, 'package.json'),
                    { basedir: packagePath }
                );
                const dir:string = path.dirname(modulePath);
                results.appendProd(dir);

                // For any production modules that have a .syncignore file, 
                // we should apply that to the .syncignore cache
                results.appendFile(dir);

                // Do a search within this module and pass along the results
                this._search(dir, results);
            }
            catch(e) {
                // do nothing
            }
        }

        // Process the remaining node_modules
        // if they aren't in production, we should remove them
        this._searchRemainder(packagePath, results);
    }

    /**
     * Get the rest of the node_modules and add everything else
     * the results should consider anything else that isn't
     * already defined as a production dependency to be dev and ignored.
     * @function SyncIgnore#_searchRemainder
     * @private
     * @param {string} packagePath root path
     * @param {SearchResults} results The results to update
     */
    private _searchRemainder(packagePath:string, results:SearchResults): void
    {
        const dir:string = path.join(packagePath, 'node_modules');

        // Ignore missing node_modules folder
        if (!fs.existsSync(dir)) {
            return;
        }

        const folders:string[] = fs.readdirSync(dir);

        // Create a list of folders without namespaces
        const list = folders.filter(folder => {
            return folder[0] !== '@';
        });

        // Get all the folders within the individual 
        // namespace folders
        let namespacesList:string[] = [];
        const namespaces:string[] = folders.filter(folder => {
            return folder[0] === '@';
        });

        //  Get all the folders
        namespaces.forEach(ns => {
            const nsDir:string = path.join(packagePath, 'node_modules', ns);
            namespacesList = namespacesList.concat(
                // Prepend all items with the namesapce
                fs.readdirSync(nsDir).map(name => {
                    return path.join(ns, name);
                })
            );
        });

        results.appendAll([]
            .concat(namespacesList)
            .concat(list),
            dir
        );
    }
}
