import * as path from 'path';
import * as fs from 'fs';
import SyncIgnore from './SyncIgnore';

/**
 * The results when searching for packages.
 * @class SearchResults
 * @private
 */
export default class SearchResults {

    /**
     * The raw list of dev packages to ignore
     * @name SearchResult#dev
     * @type {string[]}
     * @private
     */
    private _dev:string[];

    /**
     * The raw list of dev packages to include
     * @name SearchResult#prod
     * @type {string[]}
     * @private
     */
    private _prod:string[];

    /**
     * The collection of all node_modules
     * by walking through the tree.
     * @name SearchResult#_all
     * @type {string[]}
     * @private
     */
    private _all:string[];

    /**
     * The current working directory
     * @name SearchResult#cwd
     * @type {string}
     * @private
     */
    private _cwd:string;

    /**
     * @constructor
     */
    constructor(cwd:string) {
        this._cwd = cwd;
        this._dev = [];
        this._prod = [];
        this._all = [];
    }

    /**
     * Remove the redundant options and excludes
     * any production modules.
     * @method SearchResult#process
     * @return {string[]} List of packages ignore list
     */
    public process(): string[] {

        // If it isn't in the production list
        // and it isn't in the dev list, consider a dev dependency
        this._all.forEach((curr) => {
            if (this._prod.indexOf(curr) < 0 && this._dev.indexOf(curr) < 0) {
                this._dev.push(curr);
            }
        });

        return this._dev.filter((item) => {
            // Do not add modules which are resolved above
            // the current working directory
            return item.slice(0, 4) !== path.sep + '..' + path.sep;
        }).filter((item) => {
            // Remove any production dependencies
            // usually this is because they were de-duped
            // and are shared between dev and prod deps
            return this._prod.indexOf(item) === -1;
        }).map((item) => {
            // normalize Windows paths
            return item.replace(/\\/g, '/');
        }).sort();
    }

    /**
     * For sub modules, we'll add the .syncignore file to ignore
     * any local files that shouldn't be synced.
     * @method SearchResult#appendFile
     * @param {string} dir Root directory of module
     */
    public appendFile(dir:string): void {
        const syncIgnorePath:string = path.join(dir, SyncIgnore.FILENAME_LOCAL);

        // Check that file exists
        if (!fs.existsSync(syncIgnorePath)) {
            return;
        }
        const list:string[] = fs.readFileSync(syncIgnorePath, 'utf8').split('\n');
        this.appendDevList(list, dir);
    }

    /**
     * Add a list of item to append to dev
     * @method SearchResult#appendDevList
     * @param {string[]} list The list of entries from .syncignore
     * @param {string} [dir] Root directory of module if list are relative
     */
    public appendDevList(list:string[], dir?:string): void {
        list.forEach(ignore => {
            if (ignore) {
                if (dir) {
                    const sep:string = ignore[0] !== path.sep ? path.sep : '';
                    this.appendDev(dir + sep + ignore);
                }
                else {
                    this.appendDev(ignore);
                }
            }
        });
    }

    /**
     * Add the list of remaining files.
     * @method SearchResult#appendAll
     * @param {string[]} list The list of relative entries from .syncignore
     */
    public appendAll(list:string[], dir:string): void {
        list.forEach(ignore => {
            if (ignore) {
                const modulePath:string = path.join(dir, ignore);
                const curr:string = path.sep + path.relative(this._cwd, modulePath);
                this._all.push(curr);
            }
        });
    }

    /**
     * Add to the list of dev dependencies we should ignore
     * @method SearchResult#appendDev
     * @param {string} modulePath The root directory
     */
    public appendDev(modulePath:string): void {
        const curr:string = path.sep + path.relative(this._cwd, modulePath);
        // Check for duplicates
        if (this._dev.indexOf(curr) < 0) {
            this._dev.push(curr);
        }
    }

    /**
     * Add to the list of production dependencies we should not ignore
     * @method SearchResult#appendProd
     * @param {string} modulePath The root directory
     */
    public appendProd(modulePath:string): void {
        const curr:string = path.sep + path.relative(this._cwd, modulePath);
        if (this._prod.indexOf(curr) < 0) {
            this._prod.push(curr);
        }
    }

    /**
     * Destroy and don't use after this
     * @method SearchResult#destroy
     */
    public destroy(): void {
        this._dev = null;
        this._prod = null;
        this._cwd = null;
    }
}
